INSERT INTO `programs` VALUES (1,1,'Nhóm trẻ dưới 12 tháng','2025-11-16 17:44:29','2026-07-23 17:49:02',6,2500000,17,'nhom-tre-duoi-12-thang',NULL,'<p><strong>Giới thiệu chương trình chăm sóc – giáo dục trẻ dưới 12 tháng tuổi</strong></p><p>Giai đoạn dưới 12 tháng tuổi là bước khởi đầu quan trọng trong hành trình phát triển của trẻ. Đây là thời kỳ trẻ phát triển rất nhanh về thể chất, giác quan và khả năng nhận biết thế giới xung quanh. Chương trình chăm sóc – giáo dục dành cho trẻ dưới 12 tháng được xây dựng với mục tiêu tạo môi trường an toàn, yêu thương và gần gũi, giúp trẻ phát triển khỏe mạnh cả về thể chất lẫn cảm xúc.</p><p>Trong môi trường lớp học thân thiện, trẻ được chăm sóc chu đáo theo nhịp sinh hoạt cá nhân, đồng thời được tiếp xúc với các hoạt động kích thích giác quan và vận động phù hợp với từng giai đoạn phát triển. Giáo viên luôn quan sát, tương tác nhẹ nhàng và khuyến khích trẻ khám phá thế giới xung quanh thông qua các hoạt động đơn giản và gần gũi.</p><p><strong>Mục tiêu chương trình</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển thể chất:</strong> Hỗ trợ trẻ phát triển các kỹ năng vận động cơ bản như lẫy, bò, ngồi, đứng và bước đi những bước đầu tiên.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Kích thích giác quan:</strong> Tăng cường khả năng cảm nhận thông qua âm thanh, màu sắc, hình ảnh và các đồ chơi phù hợp với độ tuổi.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển ngôn ngữ:</strong> Khuyến khích trẻ phản ứng với âm thanh, tập bập bẹ, nhận biết giọng nói quen thuộc và giao tiếp bằng biểu cảm.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển cảm xúc:</strong> Tạo cảm giác an toàn, gắn bó và tin tưởng thông qua sự chăm sóc ân cần của giáo viên.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Hình thành nề nếp sinh hoạt:</strong> Xây dựng thói quen ăn, ngủ, vệ sinh và sinh hoạt phù hợp với từng trẻ.</li></ol><p><strong>Phương pháp chăm sóc – giáo dục</strong></p><p>Chương trình áp dụng phương pháp chăm sóc cá nhân hóa, tôn trọng nhịp sinh hoạt riêng của từng trẻ. Giáo viên luôn theo dõi sát sao, tương tác tích cực và tạo nhiều cơ hội để trẻ vận động, khám phá và cảm nhận môi trường xung quanh.</p><p>Không gian lớp học được thiết kế an toàn, sạch sẽ, nhiều học cụ trực quan và đồ chơi phù hợp với trẻ nhỏ, giúp trẻ phát triển các giác quan và vận động một cách tự nhiên.</p><p>Với sự chăm sóc tận tình cùng môi trường yêu thương và an toàn, trẻ dưới 12 tháng tuổi sẽ được nuôi dưỡng khỏe mạnh, hình thành cảm giác an toàn và những nền tảng phát triển đầu đời vững chắc.</p>',5,6,12),(2,1,'Nhóm trẻ 12 đến 24 tháng','2025-11-16 17:44:29','2026-07-23 17:49:10',15,1800000,18,'nhom-tre-12-den-24-thang',NULL,'<p><strong>Giới thiệu chương trình chăm sóc – giáo dục trẻ 12–24 tháng</strong></p><p>Giai đoạn 12–24 tháng là thời kỳ trẻ bắt đầu khám phá thế giới xung quanh một cách chủ động hơn. Trẻ tập đi, tập nói những từ đầu tiên và dần hình thành sự tự lập trong một số hoạt động đơn giản. Chương trình chăm sóc – giáo dục dành cho trẻ 12–24 tháng được xây dựng nhằm tạo môi trường an toàn, ấm áp và đầy yêu thương, giúp trẻ phát triển toàn diện cả về thể chất, nhận thức và cảm xúc.</p><p>Trong môi trường lớp học thân thiện, trẻ được tham gia nhiều hoạt động trải nghiệm phù hợp với lứa tuổi như vận động, chơi với đồ vật, nghe nhạc, nghe kể chuyện và khám phá các đồ chơi kích thích giác quan. Mỗi hoạt động đều được thiết kế đơn giản, sinh động để trẻ vừa học vừa chơi một cách tự nhiên và vui vẻ.</p><p><strong>Mục tiêu chương trình</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển vận động:</strong> Hỗ trợ trẻ rèn luyện các kỹ năng như đứng, đi vững, leo trèo, cầm nắm đồ vật và phối hợp tay – mắt thông qua các hoạt động vận động và trò chơi.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển ngôn ngữ:</strong> Khuyến khích trẻ bập bẹ, nói các từ đơn giản, gọi tên đồ vật quen thuộc và phản hồi khi được trò chuyện.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển nhận thức:</strong> Giúp trẻ nhận biết màu sắc, hình dạng, âm thanh và các sự vật quen thuộc trong cuộc sống hằng ngày.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển cảm xúc – xã hội:</strong> Tạo cảm giác an toàn, giúp trẻ mạnh dạn giao tiếp với giáo viên, làm quen với bạn bè và tham gia các hoạt động chung.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Hình thành thói quen sinh hoạt:</strong> Hướng dẫn trẻ hình thành những thói quen tốt như ăn uống, ngủ nghỉ đúng giờ, rửa tay và cất đồ chơi sau khi chơi.</li></ol><p><strong>Phương pháp chăm sóc – giáo dục</strong></p><p>Chương trình áp dụng phương pháp chăm sóc kết hợp giáo dục sớm, lấy trẻ làm trung tâm và tôn trọng nhịp phát triển riêng của từng trẻ. Giáo viên luôn quan sát, lắng nghe và tương tác nhẹ nhàng để hỗ trợ trẻ phát triển một cách tự nhiên.</p><p>Không gian lớp học được thiết kế an toàn, sạch sẽ với nhiều học cụ trực quan và đồ chơi phù hợp với độ tuổi, tạo điều kiện để trẻ vận động, khám phá và phát triển các giác quan.</p><p>Với môi trường chăm sóc tận tình và chương trình học phù hợp, trẻ 12–24 tháng sẽ từng bước phát triển sự tự tin, khả năng giao tiếp và những kỹ năng nền tảng cho các giai đoạn học tập tiếp theo.</p>',3,12,24),(3,1,'Nhóm trẻ 24 đến 36 tháng','2025-11-16 17:51:58','2026-07-23 17:50:03',20,1800000,19,'nhom-tre-24-den-36-thang',NULL,'<p><strong>Giới thiệu chương trình học Nhóm trẻ 24–36 tháng</strong></p><p>Giai đoạn 24–36 tháng là thời điểm trẻ phát triển mạnh mẽ về vận động, ngôn ngữ và khả năng khám phá thế giới xung quanh. Trẻ bắt đầu hình thành tính tự lập, thích giao tiếp, bắt chước và tham gia vào nhiều hoạt động khác nhau. Chương trình Nhóm trẻ 24–36 tháng được xây dựng nhằm tạo môi trường học tập an toàn, yêu thương và giàu trải nghiệm để trẻ phát triển toàn diện ngay từ những năm đầu đời.</p><p>Thông qua các hoạt động vui chơi, trải nghiệm và tương tác với giáo viên, bạn bè, trẻ được khuyến khích khám phá, vận động và thể hiện cảm xúc của mình. Các bài học được thiết kế đơn giản, sinh động, phù hợp với khả năng tiếp nhận của trẻ nhỏ, giúp trẻ học tập một cách tự nhiên và hứng thú.</p><p><strong>Mục tiêu chương trình</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển vận động:</strong> Tăng cường các kỹ năng vận động cơ bản như đi, chạy, leo trèo, cầm nắm đồ vật và phối hợp tay – mắt thông qua các trò chơi vận động và hoạt động trải nghiệm.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển ngôn ngữ:</strong> Khuyến khích trẻ nói những từ đơn giản, gọi tên đồ vật quen thuộc, nghe hiểu lời nói và giao tiếp với giáo viên, bạn bè.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển nhận thức:</strong> Giúp trẻ nhận biết màu sắc, hình dạng, âm thanh và một số sự vật quen thuộc trong cuộc sống hằng ngày.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển cảm xúc – xã hội:</strong> Hình thành sự tự tin, khả năng tương tác với người xung quanh, bước đầu học cách chia sẻ và tham gia các hoạt động tập thể.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Hình thành thói quen sinh hoạt:</strong> Rèn luyện các thói quen tốt như ăn uống đúng giờ, rửa tay, cất đồ chơi và làm quen với nề nếp sinh hoạt tại lớp.</li></ol><p><strong>Phương pháp giáo dục</strong></p><p>Chương trình áp dụng phương pháp giáo dục lấy trẻ làm trung tâm, chú trọng việc học thông qua trải nghiệm và tương tác. Giáo viên luôn quan sát, lắng nghe và hỗ trợ để mỗi trẻ được phát triển theo khả năng và nhịp độ riêng của mình.</p><p>Môi trường lớp học được thiết kế thân thiện, an toàn và nhiều học liệu trực quan, giúp trẻ thoải mái khám phá, vui chơi và hình thành niềm yêu thích khi đến trường mỗi ngày.</p><p>Với sự chăm sóc tận tình của giáo viên cùng chương trình học phù hợp, trẻ 24–36 tháng sẽ dần phát triển sự tự tin, khả năng giao tiếp và những kỹ năng cơ bản cho các giai đoạn học tập tiếp theo.</p>',20,24,36),(4,1,'Mẫu giáo bé (3-4 tuổi)','2025-11-16 17:52:15','2026-07-23 17:50:33',25,1800000,20,'mau-giao-be-3-4-tuoi',NULL,'<p><strong>Giới thiệu chương trình học Mẫu giáo bé (3–4 tuổi)</strong></p><p>Độ tuổi 3–4 là giai đoạn trẻ bắt đầu mở rộng thế giới của mình, từ gia đình đến môi trường tập thể. Trẻ trở nên tò mò, thích khám phá, học hỏi và thể hiện cảm xúc một cách rõ ràng hơn. Chương trình Mẫu giáo bé được xây dựng nhằm giúp trẻ phát triển những kỹ năng nền tảng về nhận thức, ngôn ngữ, thể chất và kỹ năng xã hội thông qua các hoạt động vui chơi và trải nghiệm phù hợp với lứa tuổi.</p><p>Trong môi trường học tập thân thiện và an toàn, trẻ được khuyến khích khám phá thế giới xung quanh bằng nhiều hoạt động phong phú như trò chơi học tập, kể chuyện, âm nhạc, mỹ thuật và vận động. Việc học được lồng ghép trong các hoạt động vui chơi giúp trẻ tiếp thu kiến thức một cách tự nhiên, tạo hứng thú và niềm vui khi đến lớp mỗi ngày.</p><p><strong>Mục tiêu chương trình</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển nhận thức:</strong> Giúp trẻ bước đầu nhận biết màu sắc, hình dạng, kích thước, đồng thời làm quen với các khái niệm đơn giản như đếm số, phân loại và so sánh.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển ngôn ngữ:</strong> Tăng cường khả năng nghe – hiểu, khuyến khích trẻ nói rõ ràng, diễn đạt ý nghĩ và giao tiếp với bạn bè, giáo viên.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển kỹ năng xã hội:</strong> Giúp trẻ làm quen với môi trường tập thể, học cách chia sẻ, hợp tác và tuân thủ các quy tắc đơn giản trong lớp học.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển thể chất:</strong> Rèn luyện các kỹ năng vận động cơ bản như chạy, nhảy, leo trèo và giữ thăng bằng thông qua các trò chơi vận động và hoạt động ngoài trời.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển thẩm mỹ và sáng tạo:</strong> Khuyến khích trẻ thể hiện trí tưởng tượng và cảm xúc qua các hoạt động vẽ, tô màu, hát, múa và làm đồ thủ công.</li></ol><p><strong>Phương pháp giáo dục</strong></p><p>Chương trình áp dụng phương pháp giáo dục lấy trẻ làm trung tâm, chú trọng việc học thông qua trải nghiệm và tương tác. Giáo viên đóng vai trò hướng dẫn, khơi gợi sự tò mò và tạo điều kiện để trẻ tự tin tham gia các hoạt động.</p><p>Môi trường lớp học được thiết kế sinh động, nhiều học liệu trực quan, giúp trẻ phát triển khả năng quan sát, khám phá và hình thành niềm yêu thích học tập ngay từ những năm đầu đời.</p><p>Với chương trình học phù hợp cùng sự chăm sóc tận tình của giáo viên, trẻ 3–4 tuổi sẽ dần hình thành sự tự tin, tính tự lập và những kỹ năng cơ bản để tiếp tục phát triển ở các giai đoạn học tập tiếp theo.</p>',12,36,48),(5,1,'Mẫu giáo nhỡ (4-5 tuổi)','2025-11-18 16:41:18','2026-07-23 17:51:11',20,1800000,21,'mau-giao-nho-4-5-tuoi',NULL,'<p><strong>Giới thiệu chương trình học Mẫu giáo nhỡ (4–5 tuổi)</strong></p><p>Độ tuổi 4–5 là giai đoạn trẻ phát triển mạnh mẽ về trí tuệ, ngôn ngữ và khả năng giao tiếp xã hội. Trẻ bắt đầu đặt nhiều câu hỏi, tò mò khám phá thế giới xung quanh và thể hiện rõ cá tính của mình. Chương trình Mẫu giáo nhỡ được xây dựng nhằm khuyến khích sự ham học hỏi, phát triển tư duy và bồi dưỡng các kỹ năng cần thiết cho trẻ trong quá trình trưởng thành.</p><p>Thông qua các hoạt động học tập đa dạng, trẻ được tham gia vào nhiều trải nghiệm thú vị như khám phá khoa học, trò chơi tư duy, hoạt động nghệ thuật và vận động thể chất. Việc học được lồng ghép trong các trò chơi và hoạt động trải nghiệm, giúp trẻ tiếp thu kiến thức một cách tự nhiên và đầy hứng thú.</p><p><strong>Mục tiêu chương trình</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển nhận thức:</strong> Giúp trẻ nhận biết và phân biệt màu sắc, hình dạng, kích thước; bước đầu làm quen với các khái niệm toán học đơn giản như đếm số, so sánh và sắp xếp.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển ngôn ngữ:</strong> Mở rộng vốn từ, khuyến khích trẻ diễn đạt suy nghĩ, kể chuyện, đặt câu hỏi và giao tiếp tự tin với mọi người xung quanh.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển kỹ năng xã hội:</strong> Hình thành khả năng hợp tác, chia sẻ, tôn trọng bạn bè và tham gia tích cực vào các hoạt động nhóm.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển thể chất:</strong> Rèn luyện sức khỏe và sự khéo léo thông qua các trò chơi vận động, hoạt động ngoài trời và các bài tập thể dục phù hợp với lứa tuổi.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển thẩm mỹ và sáng tạo:</strong> Khuyến khích trẻ thể hiện cảm xúc và trí tưởng tượng thông qua vẽ, tô màu, hát, múa và các hoạt động thủ công.</li></ol><p><strong>Phương pháp giáo dục</strong></p><p>Chương trình áp dụng phương pháp giáo dục lấy trẻ làm trung tâm, tạo điều kiện để trẻ được chủ động tham gia và trải nghiệm. Giáo viên đóng vai trò hướng dẫn, khơi gợi sự tò mò và hỗ trợ trẻ trong quá trình khám phá, học hỏi.</p><p>Môi trường lớp học được thiết kế thân thiện, an toàn và giàu học liệu, giúp trẻ tự do khám phá, phát triển sự tự tin, tính độc lập và niềm yêu thích học tập.</p><p>Với chương trình học phù hợp cùng sự quan tâm, chăm sóc tận tình của giáo viên, trẻ 4–5 tuổi sẽ được phát triển toàn diện và sẵn sàng bước vào giai đoạn Mẫu giáo lớn với nhiều kỹ năng và trải nghiệm tích cực.</p>',12,48,60),(6,1,'Mẫu giáo lớn (5-6 tuổi)','2025-11-18 16:41:43','2026-07-23 17:51:35',12,1200000,22,'mau-giao-lon-5-6-tuoi',NULL,'<p><strong>Giới thiệu chương trình học Mẫu giáo lớn (5–6 tuổi)</strong></p><p>Độ tuổi 5–6 là giai đoạn quan trọng giúp trẻ hoàn thiện những kỹ năng cần thiết trước khi bước vào lớp Một. Chương trình Mẫu giáo lớn được xây dựng nhằm phát triển toàn diện cho trẻ về trí tuệ, thể chất, ngôn ngữ, tình cảm và kỹ năng xã hội, đồng thời tạo nền tảng vững chắc cho quá trình học tập ở bậc Tiểu học.</p><p>Thông qua các hoạt động học tập phong phú và sinh động, trẻ được khuyến khích chủ động khám phá, đặt câu hỏi, tư duy và thể hiện ý tưởng của mình. Các bài học được thiết kế phù hợp với đặc điểm tâm sinh lý của trẻ, giúp trẻ học tập trong môi trường vui vẻ, tích cực và đầy cảm hứng.</p><p><strong>Mục tiêu chương trình</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển nhận thức:</strong> Giúp trẻ làm quen với các khái niệm cơ bản về toán học như số lượng, so sánh, phân loại, hình dạng; đồng thời mở rộng hiểu biết về thế giới xung quanh thông qua các hoạt động khám phá khoa học.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển ngôn ngữ:</strong> Tăng cường khả năng nghe – nói, mở rộng vốn từ, giúp trẻ tự tin giao tiếp, kể chuyện và bày tỏ suy nghĩ của mình.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Chuẩn bị kỹ năng tiền tiểu học:</strong> Làm quen với chữ cái, chữ số, rèn luyện khả năng tập trung, kỹ năng cầm bút, tư duy logic và thói quen học tập.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển kỹ năng xã hội:</strong> Rèn luyện khả năng hợp tác, làm việc nhóm, biết chia sẻ, tôn trọng bạn bè và tuân thủ các quy tắc chung.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển thể chất:</strong> Tăng cường vận động thông qua các hoạt động thể dục, trò chơi vận động và hoạt động ngoài trời, giúp trẻ khỏe mạnh và năng động.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Phát triển thẩm mỹ và sáng tạo:</strong> Khuyến khích trẻ thể hiện cảm xúc và trí tưởng tượng thông qua âm nhạc, mỹ thuật, múa và các hoạt động sáng tạo.</li></ol><p><strong>Phương pháp giáo dục</strong></p><p>Chương trình áp dụng phương pháp giáo dục lấy trẻ làm trung tâm, kết hợp giữa học tập và trải nghiệm thực tế. Trẻ được tham gia các hoạt động đa dạng như trò chơi học tập, thí nghiệm đơn giản, hoạt động nhóm, kể chuyện, đóng vai và khám phá thiên nhiên.</p><p>Môi trường lớp học được xây dựng thân thiện, kích thích sự tò mò và sáng tạo của trẻ, đồng thời tạo điều kiện để mỗi trẻ phát huy tối đa khả năng của mình.</p><p>Với chương trình học được thiết kế khoa học cùng sự đồng hành tận tâm của giáo viên, trẻ 5–6 tuổi sẽ hình thành sự tự tin, tính chủ động và những kỹ năng cần thiết để sẵn sàng bước vào hành trình học tập mới ở bậc Tiểu học.</p>',2,60,72),(20,1,'test program','2026-03-10 17:47:02','2026-03-10 17:47:07',NULL,250000,486,'test-program','2026-03-10 17:47:07',NULL,NULL,NULL,NULL),(21,1,'test program','2026-03-10 17:48:02','2026-03-10 18:01:26',NULL,1500000,490,'test-program','2026-03-10 18:01:26',NULL,NULL,NULL,NULL),(22,1,'Test program','2026-03-10 18:04:57','2026-03-11 02:56:19',NULL,750000,501,NULL,'2026-03-11 02:56:19','<p><strong>Chương tr&igrave;nh Mầm non d&agrave;nh cho trẻ 18&ndash;24 th&aacute;ng tuổi</strong></p>\r\n<p>Giai đoạn 18&ndash;24 th&aacute;ng l&agrave; thời kỳ v&agrave;ng cho sự ph&aacute;t triển to&agrave;n diện của trẻ. Ở độ tuổi n&agrave;y, trẻ bắt đầu kh&aacute;m ph&aacute; thế giới xung quanh một c&aacute;ch mạnh mẽ, ph&aacute;t triển nhanh về ng&ocirc;n ngữ, vận động, cảm x&uacute;c v&agrave; kỹ năng x&atilde; hội. Chương tr&igrave;nh mầm non d&agrave;nh cho trẻ 18&ndash;24 th&aacute;ng được thiết kế nhằm tạo ra m&ocirc;i trường an to&agrave;n, ấm &aacute;p v&agrave; gi&agrave;u trải nghiệm để trẻ ph&aacute;t triển tự nhi&ecirc;n theo nhịp độ của m&igrave;nh.</p>\r\n<p>Th&ocirc;ng qua c&aacute;c hoạt động học m&agrave; chơi &ndash; chơi m&agrave; học, trẻ được khuyến kh&iacute;ch kh&aacute;m ph&aacute;, thử nghiệm v&agrave; b&agrave;y tỏ cảm x&uacute;c. C&aacute;c b&agrave;i học được x&acirc;y dựng ngắn gọn, sinh động, ph&ugrave; hợp với khả năng tập trung của trẻ nhỏ, gi&uacute;p trẻ h&igrave;nh th&agrave;nh những kỹ năng nền tảng quan trọng cho giai đoạn ph&aacute;t triển tiếp theo.</p>\r\n<p><strong>Mục ti&ecirc;u chương tr&igrave;nh</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Ph&aacute;t triển vận động:</strong> R&egrave;n luyện kỹ năng đi, chạy, leo tr&egrave;o, cầm nắm v&agrave; phối hợp tay &ndash; mắt th&ocirc;ng qua c&aacute;c tr&ograve; chơi vận động v&agrave; hoạt động trải nghiệm.</p>\r\n</li>\r\n<li>\r\n<p><strong>Ph&aacute;t triển ng&ocirc;n ngữ:</strong> Khuyến kh&iacute;ch trẻ giao tiếp, gọi t&ecirc;n đồ vật, nghe hiểu v&agrave; phản hồi th&ocirc;ng qua b&agrave;i h&aacute;t, kể chuyện v&agrave; tr&ograve; chuyện c&ugrave;ng gi&aacute;o vi&ecirc;n.</p>\r\n</li>\r\n<li>\r\n<p><strong>Ph&aacute;t triển nhận thức:</strong> Gi&uacute;p trẻ nhận biết m&agrave;u sắc, h&igrave;nh dạng, &acirc;m thanh v&agrave; c&aacute;c sự vật quen thuộc trong cuộc sống hằng ng&agrave;y.</p>\r\n</li>\r\n<li>\r\n<p><strong>Ph&aacute;t triển cảm x&uacute;c &ndash; x&atilde; hội:</strong> H&igrave;nh th&agrave;nh sự tự tin, khả năng tương t&aacute;c với bạn b&egrave; v&agrave; gi&aacute;o vi&ecirc;n, biết chia sẻ v&agrave; l&agrave;m quen với m&ocirc;i trường tập thể.</p>\r\n</li>\r\n<li>\r\n<p><strong>H&igrave;nh th&agrave;nh th&oacute;i quen tốt:</strong> R&egrave;n luyện c&aacute;c kỹ năng tự phục vụ đơn giản như ăn uống, rửa tay, cất đồ chơi v&agrave; tu&acirc;n thủ nề nếp sinh hoạt.</p>\r\n</li>\r\n</ul>\r\n<p><strong>Phương ph&aacute;p gi&aacute;o dục</strong></p>\r\n<p>Chương tr&igrave;nh &aacute;p dụng phương ph&aacute;p gi&aacute;o dục t&iacute;ch cực, lấy trẻ l&agrave;m trung t&acirc;m. Gi&aacute;o vi&ecirc;n đ&oacute;ng vai tr&ograve; người đồng h&agrave;nh, quan s&aacute;t v&agrave; hỗ trợ để mỗi trẻ được ph&aacute;t triển theo khả năng v&agrave; sở th&iacute;ch ri&ecirc;ng. M&ocirc;i trường lớp học được thiết kế th&acirc;n thiện, nhiều học cụ trực quan, gi&uacute;p trẻ học tập th&ocirc;ng qua trải nghiệm thực tế.</p>\r\n<p>Với sự chăm s&oacute;c tận t&igrave;nh của gi&aacute;o vi&ecirc;n v&agrave; m&ocirc;i trường học tập an to&agrave;n, trẻ 18&ndash;24 th&aacute;ng sẽ từng bước ph&aacute;t triển sự tự lập, t&ograve; m&ograve; kh&aacute;m ph&aacute; v&agrave; niềm vui khi đến trường mỗi ng&agrave;y.</p>',NULL,NULL,NULL),(23,1,'Test program','2026-03-10 18:05:27','2026-03-12 06:27:03',NULL,750000,501,'test-program','2026-03-12 06:27:03','<p><strong>Chương tr&igrave;nh Mầm non d&agrave;nh cho trẻ 18&ndash;24 th&aacute;ng tuổi</strong></p>\r\n<p>Giai đoạn 18&ndash;24 th&aacute;ng l&agrave; thời kỳ v&agrave;ng cho sự ph&aacute;t triển to&agrave;n diện của trẻ. Ở độ tuổi n&agrave;y, trẻ bắt đầu kh&aacute;m ph&aacute; thế giới xung quanh một c&aacute;ch mạnh mẽ, ph&aacute;t triển nhanh về ng&ocirc;n ngữ, vận động, cảm x&uacute;c v&agrave; kỹ năng x&atilde; hội. Chương tr&igrave;nh mầm non d&agrave;nh cho trẻ 18&ndash;24 th&aacute;ng được thiết kế nhằm tạo ra m&ocirc;i trường an to&agrave;n, ấm &aacute;p v&agrave; gi&agrave;u trải nghiệm để trẻ ph&aacute;t triển tự nhi&ecirc;n theo nhịp độ của m&igrave;nh.</p>\r\n<p>Th&ocirc;ng qua c&aacute;c hoạt động học m&agrave; chơi &ndash; chơi m&agrave; học, trẻ được khuyến kh&iacute;ch kh&aacute;m ph&aacute;, thử nghiệm v&agrave; b&agrave;y tỏ cảm x&uacute;c. C&aacute;c b&agrave;i học được x&acirc;y dựng ngắn gọn, sinh động, ph&ugrave; hợp với khả năng tập trung của trẻ nhỏ, gi&uacute;p trẻ h&igrave;nh th&agrave;nh những kỹ năng nền tảng quan trọng cho giai đoạn ph&aacute;t triển tiếp theo.</p>\r\n<p><strong>Mục ti&ecirc;u chương tr&igrave;nh</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Ph&aacute;t triển vận động:</strong> R&egrave;n luyện kỹ năng đi, chạy, leo tr&egrave;o, cầm nắm v&agrave; phối hợp tay &ndash; mắt th&ocirc;ng qua c&aacute;c tr&ograve; chơi vận động v&agrave; hoạt động trải nghiệm.</p>\r\n</li>\r\n<li>\r\n<p><strong>Ph&aacute;t triển ng&ocirc;n ngữ:</strong> Khuyến kh&iacute;ch trẻ giao tiếp, gọi t&ecirc;n đồ vật, nghe hiểu v&agrave; phản hồi th&ocirc;ng qua b&agrave;i h&aacute;t, kể chuyện v&agrave; tr&ograve; chuyện c&ugrave;ng gi&aacute;o vi&ecirc;n.</p>\r\n</li>\r\n<li>\r\n<p><strong>Ph&aacute;t triển nhận thức:</strong> Gi&uacute;p trẻ nhận biết m&agrave;u sắc, h&igrave;nh dạng, &acirc;m thanh v&agrave; c&aacute;c sự vật quen thuộc trong cuộc sống hằng ng&agrave;y.</p>\r\n</li>\r\n<li>\r\n<p><strong>Ph&aacute;t triển cảm x&uacute;c &ndash; x&atilde; hội:</strong> H&igrave;nh th&agrave;nh sự tự tin, khả năng tương t&aacute;c với bạn b&egrave; v&agrave; gi&aacute;o vi&ecirc;n, biết chia sẻ v&agrave; l&agrave;m quen với m&ocirc;i trường tập thể.</p>\r\n</li>\r\n<li>\r\n<p><strong>H&igrave;nh th&agrave;nh th&oacute;i quen tốt:</strong> R&egrave;n luyện c&aacute;c kỹ năng tự phục vụ đơn giản như ăn uống, rửa tay, cất đồ chơi v&agrave; tu&acirc;n thủ nề nếp sinh hoạt.</p>\r\n</li>\r\n</ul>\r\n<p><strong>Phương ph&aacute;p gi&aacute;o dục</strong></p>\r\n<p>Chương tr&igrave;nh &aacute;p dụng phương ph&aacute;p gi&aacute;o dục t&iacute;ch cực, lấy trẻ l&agrave;m trung t&acirc;m. Gi&aacute;o vi&ecirc;n đ&oacute;ng vai tr&ograve; người đồng h&agrave;nh, quan s&aacute;t v&agrave; hỗ trợ để mỗi trẻ được ph&aacute;