INSERT INTO `users` VALUES (1,'QDZ','admin@mamnonbanmai.blog',NULL,'$2y$12$g37fvo9GMvgAIvkrUpPx3uhtcEIjIsdBSd6W4thh2CVtTDOxIJERm',NULL,NULL,'2026-07-23 18:12:23',1,33,'nguyen_van','0369160687',NULL,'Dia chi thu 2',NULL,'luuanhquyen','<p><strong>Người Giáo Viên Mầm Non – Trái Tim Yêu Nghề Từ Đại Học Sư Phạm</strong></p><p>Trong xã hội, giáo viên mầm non là những người đặt nền móng đầu tiên cho sự phát triển của mỗi con người. Họ không chỉ dạy trẻ những bài học đơn giản như hát, vẽ, đọc chữ, mà còn gieo vào tâm hồn trẻ thơ những hạt giống đầu tiên của nhân cách, tình yêu thương và sự tự tin.</p><p>Một giáo viên mầm non tốt nghiệp từ <strong>Đại học Sư phạm Quốc gia</strong> thường mang trong mình nền tảng kiến thức vững vàng cùng tinh thần trách nhiệm cao với nghề. Quá trình học tập tại trường không chỉ trang bị kiến thức về tâm lý trẻ em, phương pháp giáo dục hiện đại, mà còn rèn luyện cho sinh viên sự kiên nhẫn, lòng yêu thương và khả năng chăm sóc trẻ nhỏ một cách toàn diện.</p><p>Với tình yêu nghề sâu sắc, người giáo viên mầm non luôn xem mỗi đứa trẻ như chính con của mình. Từng cử chỉ nhỏ như buộc lại dây giày, lau nước mắt khi trẻ buồn hay kiên nhẫn dạy trẻ phát âm từng chữ đều thể hiện sự tận tâm và lòng nhiệt huyết với nghề. Đối với họ, niềm vui lớn nhất chính là được nhìn thấy các em lớn lên từng ngày, tự tin hơn, ngoan ngoãn hơn và biết yêu thương mọi người xung quanh.</p><p>Ngoài việc chăm sóc và dạy dỗ trẻ, giáo viên mầm non còn đóng vai trò cầu nối giữa gia đình và nhà trường. Họ thường xuyên trao đổi với phụ huynh để hiểu rõ tính cách, thói quen và nhu cầu của từng trẻ, từ đó có phương pháp giáo dục phù hợp nhất. Sự phối hợp chặt chẽ này giúp trẻ phát triển cả về trí tuệ, thể chất lẫn cảm xúc.</p><p>Trở thành giáo viên mầm non là lựa chọn của những người thật sự yêu trẻ và yêu nghề. Những người tốt nghiệp từ Đại học Sư phạm Quốc gia không chỉ mang theo tấm bằng đại học, mà còn mang theo lý tưởng giáo dục và khát vọng góp phần xây dựng thế hệ tương lai.</p><p>Dù công việc đôi khi vất vả và thầm lặng, nhưng với tình yêu nghề và trách nhiệm lớn lao, người giáo viên mầm non vẫn luôn âm thầm cống hiến. Họ chính là những người thắp sáng những ước mơ đầu đời và đặt nền tảng cho tương lai của mỗi đứa trẻ.</p>','nguyen_van'),(2,'Ngô Quỳnh','quynhngo@mamnonbanmai.blog',NULL,'$2y$12$g37fvo9GMvgAIvkrUpPx3uhtcEIjIsdBSd6W4thh2CVtTDOxIJERm',NULL,NULL,'2026-03-13 07:50:55',1,294,'ngo_quynh','0369160665',NULL,'119 Lygon St, BRUNSWICK EAST, VIC, 3057',NULL,NULL,'<p><strong>Người Gi&aacute;o Vi&ecirc;n Mầm Non &ndash; Tr&aacute;i Tim Y&ecirc;u Nghề Từ Đại Học Sư Phạm</strong></p>\r\n<p>Trong x&atilde; hội, gi&aacute;o vi&ecirc;n mầm non l&agrave; những người đặt nền m&oacute;ng đầu ti&ecirc;n cho sự ph&aacute;t triển của mỗi con người. Họ kh&ocirc;ng chỉ dạy trẻ những b&agrave;i học đơn giản như h&aacute;t, vẽ, đọc chữ, m&agrave; c&ograve;n gieo v&agrave;o t&acirc;m hồn trẻ thơ những hạt giống đầu ti&ecirc;n của nh&acirc;n c&aacute;ch, t&igrave;nh y&ecirc;u thương v&agrave; sự tự tin.</p>\r\n<p>Một gi&aacute;o vi&ecirc;n mầm non tốt nghiệp từ <strong>Đại học Sư phạm Quốc gia</strong> thường mang trong m&igrave;nh nền tảng kiến thức vững v&agrave;ng c&ugrave;ng tinh thần tr&aacute;ch nhiệm cao với nghề. Qu&aacute; tr&igrave;nh học tập tại trường kh&ocirc;ng chỉ trang bị kiến thức về t&acirc;m l&yacute; trẻ em, phương ph&aacute;p gi&aacute;o dục hiện đại, m&agrave; c&ograve;n r&egrave;n luyện cho sinh vi&ecirc;n sự ki&ecirc;n nhẫn, l&ograve;ng y&ecirc;u thương v&agrave; khả năng chăm s&oacute;c trẻ nhỏ một c&aacute;ch to&agrave;n diện.</p>\r\n<p>Với t&igrave;nh y&ecirc;u nghề s&acirc;u sắc, người gi&aacute;o vi&ecirc;n mầm non lu&ocirc;n xem mỗi đứa trẻ như ch&iacute;nh con của m&igrave;nh. Từng cử chỉ nhỏ như buộc lại d&acirc;y gi&agrave;y, lau nước mắt khi trẻ buồn hay ki&ecirc;n nhẫn dạy trẻ ph&aacute;t &acirc;m từng chữ đều thể hiện sự tận t&acirc;m v&agrave; l&ograve;ng nhiệt huyết với nghề. Đối với họ, niềm vui lớn nhất ch&iacute;nh l&agrave; được nh&igrave;n thấy c&aacute;c em lớn l&ecirc;n từng ng&agrave;y, tự tin hơn, ngoan ngo&atilde;n hơn v&agrave; biết y&ecirc;u thương mọi người xung quanh.</p>\r\n<p>Ngo&agrave;i việc chăm s&oacute;c v&agrave; dạy dỗ trẻ, gi&aacute;o vi&ecirc;n mầm non c&ograve;n đ&oacute;ng vai tr&ograve; cầu nối giữa gia đ&igrave;nh v&agrave; nh&agrave; trường. Họ thường xuy&ecirc;n trao đổi với phụ huynh để hiểu r&otilde; t&iacute;nh c&aacute;ch, th&oacute;i quen v&agrave; nhu cầu của từng trẻ, từ đ&oacute; c&oacute; phương ph&aacute;p gi&aacute;o dục ph&ugrave; hợp nhất. Sự phối hợp chặt chẽ n&agrave;y gi&uacute;p trẻ ph&aacute;t triển cả về tr&iacute; tuệ, thể chất lẫn cảm x&uacute;c.</p>\r\n<p>Trở th&agrave;nh gi&aacute;o vi&ecirc;n mầm non l&agrave; lựa chọn của những người thật sự y&ecirc;u trẻ v&agrave; y&ecirc;u nghề. Những người tốt nghiệp từ Đại học Sư phạm Quốc gia kh&ocirc;ng chỉ mang theo tấm bằng đại học, m&agrave; c&ograve;n mang theo l&yacute; tưởng gi&aacute;o dục v&agrave; kh&aacute;t vọng g&oacute;p phần x&acirc;y dựng thế hệ tương lai.</p>\r\n<p>D&ugrave; c&ocirc;ng việc đ&ocirc;i khi vất vả v&agrave; thầm lặng, nhưng với t&igrave;nh y&ecirc;u nghề v&agrave; tr&aacute;ch nhiệm lớn lao, người gi&aacute;o vi&ecirc;n mầm non vẫn lu&ocirc;n &acirc;m thầm cống hiến. Họ ch&iacute;nh l&agrave; những người thắp s&aacute;ng những ước mơ đầu đời v&agrave; đặt nền tảng cho tương lai của mỗi đứa trẻ.</p>','ngo_quynh'),(3,'Nguyễn Hương','nguyenhuong@mamnonbanmai.blog',NULL,'$2y$12$g37fvo9GMvgAIvkrUpPx3uhtcEIjIsdBSd6W4thh2CVtTDOxIJERm',NULL,NULL,'2026-03-13 07:50:54',1,296,'nguyen_huong','0369160690',NULL,'Hanoi',NULL,NULL,'<p><strong>Người Gi&aacute;o Vi&ecirc;n Mầm Non &ndash; Tr&aacute;i Tim Y&ecirc;u Nghề Từ Đại Học Sư Phạm</strong></p>\r\n<p>Trong x&atilde; hội, gi&aacute;o vi&ecirc;n mầm non l&agrave; những người đặt nền m&oacute;ng đầu ti&ecirc;n cho sự ph&aacute;t triển của mỗi con người. Họ kh&ocirc;ng chỉ dạy trẻ những b&agrave;i học đơn giản như h&a